der:0;border-radius:8px;background:#d3948b;color:#fff;font:inherit;font-weight:600;cursor:pointer}.cancel{padding:14px 28px;border:1px solid #d3948b;border-radius:8px;color:#d3948b;text-decoration:none}.errors{padding:16px 20px;border-radius:10px;background:#fde5e1;color:#9b443c;margin-bottom:18px}.required{color:#c96d62}@media(max-width:700px){.page{padding:25px 16px}.grid2,.choices,.checks,.uploads{grid-template-columns:1fr 1fr}.section{padding:22px 18px}}@media(max-width:430px){.grid2,.choices,.checks,.uploads{grid-template-columns:1fr}.isbn-row{flex-direction:column}.lookup{height:44px}}</style></head><body>
