<?php if($errors):?><div class="errors"><?=implode('<br>',array_map('htmlspecialchars',$errors))?></div><?php endif; ?>
<form method="post" enctype="multipart/form-data">
<section class="section"><h2><span class="num">1</span>รายละเอียดหนังสือ</h2><div class="field"><label>ISBN <span class="required">*</span></label><div class="isbn-row"><input id="isbn" name="isbn" value="<?=old('isbn')?>" maxlength="17" placeholder="ISBN 10 หรือ 13 หลัก" required><button class="lookup" type="button" id="lookup">ค้นหาข้อมูล</button></div><div class="lookup-message" id="lookup-message">กรอก ISBN เพื่อค้นหาชื่อ ผู้แต่ง และหมวดหมู่จากข้อมูลในระบบ</div></div><div class="grid2"><div class="field"><label>ชื่อหนังสือ <span class="required">*</span></label><input id="title" name="title" value="<?=old('title')?>" required></div><div class="field"><label>ผู้แต่ง</label><input id="author" name="author" value="<?=old('author')?>"></div></div><div class="field"><label>หมวดหมู่</label><input id="category" name="category" value="<?=old('category')?>" placeholder="เช่น นวนิยาย วรรณกรรมไทย จิตวิทยา"></div></section>
<section class="section"><h2><span class="num">2</span>สภาพหนังสือ</h2><div class="choices"><?php foreach(['99'=>'99% เหมือนใหม่','90'=>'90% ดี','80'=>'80% พอใช้','70'=>'<70% อ่านเล่น'] as $v=>$label):?><label class="choice"><input type="radio" name="condition_percent" value="<?=$v?>" <?=($_POST['condition_percent']??'')===$v?'checked':''?> required><span><?=$label?></span></label><?php endforeach;?></div><p>ตำหนิเฉพาะจุด (เลือกได้มากกว่า 1 ข้อ)</p><div class="checks"><?php foreach(['จุดเหลือง','รอยพับ','ลายเซ็นเจ้าของเดิม','สันกาวหลุด','รอยไฮไลต์'] as $d):?><label class="check"><input type="checkbox" name="defects[]" value="<?=$d?>" <?=in_array($d,$_POST['defects']??[],true)?'checked':''?>> <?=$d?></label><?php endforeach;?></div></section>
<section class="section"><h2><span class="num">3</span>รายละเอียดสภาพจริง</h2><p>กรุณาอัปโหลดรูปหน้าปก และรูปมุมอื่นเพื่อให้ผู้สนใจเห็นสภาพจริง</p><div class="uploads"><?php foreach(['image_cover'=>'หน้าปก *','image_back'=>'หลังปก','image_inside'=>'สันหนังสือ','image_edge'=>'ขอบกระดาษ'] as $field=>$label):?><label class="upload"><input type="file" name="<?=$field?>" accept="image/jpeg,image/png,image/webp" <?=$field==='image_cover'?'required':''?>><span>▧<br><?=$label?></span></label><?php endforeach;?></div></section>
<section class="section"><h2><span class="num">4</span>ความต้องการในการแลกเปลี่ยน</h2><div class="choices"><?php foreach(['specific'=>'หนังสือเฉพาะเล่ม','category'=>'ตามหมวดหมู่','any'=>'เปิดรับทุกข้อเสนอ'] as $v=>$label):?><label class="choice"><input type="radio" name="wanted_type" value="<?=$v?>" <?=($_POST['wanted_type']??'')===$v?'checked':''?> required><span><?=$label?></span></label><?php endforeach;?></div><div class="field" style="margin-top:18px"><label>หนังสือหรือหมวดหมู่ที่กำลังตามหา</label><textarea name="wanted_detail"><?=old('wanted_detail')?></textarea></div></section>
<section class="section"><h2><span class="num">5</span>การจัดส่งและนัดรับ</h2><div class="checks"><?php foreach(['Thai Post','Flash Express','J&T Express','นัดรับ'] as $s):?><label class="check"><input type="checkbox" name="shipping[]" value="<?=$s?>" <?=in_array($s,$_POST['shipping']??[],true)?'checked':''?>> <?=$s?></label><?php endforeach;?></div></section>
<section class="section"><h2><span class="num">6</span>เรื่องราวของหนังสือเล่มนี้</h2><div class="field"><label>ทำไมคุณถึงส่งต่อหนังสือเล่มนี้?</label><textarea name="story_reason" placeholder="แบ่งปันความทรงจำหรือเหตุผลที่คุณรักหนังสือเล่มนี้..."><?=old('story_reason')?></textarea></div></section>
<div class="actions"><button class="publish" type="submit">ลงประกาศแลกเปลี่ยน</button><a class="cancel" href="/pages/exchange_books.php">ยกเลิก</a></div></form></main><?php require __DIR__.'/../components/footer.php';?>
<script>document.getElementById('lookup').addEventListener('click',async()=>{const isbn=document.getElementById('isbn').value,msg=document.getElementById('lookup-message');msg.textContent='กำลังค้นหา...';try{const data=await fetch('/pages/handlers/isbn_lookup.php?isbn='+encodeURIComponent(isbn)).then(r=>r.json());msg.textContent=data.message||'พบข้อมูลหนังสือแล้ว';if(data.success){['title','author','category'].forEach(k=>{if(data.book[k])document.getElementById(k).value=data.book[k];});}}catch(e){msg.textContent='ค้นหาข้อมูลไม่สำเร็จ';}});document.querySelectorAll('.upload input').forEach(input=>input.addEventListener('change',()=>{const file=input.files[0],label=input.parentElement;if(!file)return;const reader=new FileReader;reader.onload=()=>{label.querySelector('span').style.display='none';let preview=label.querySelector('img');if(!preview){preview=document.createElement('img');preview.alt='ตัวอย่างรูป';label.appendChild(preview);}preview.src=reader.result;};reader.readAsDataURL(file);}));</script></body></html>
